import '@design-schema/lit';
import { html, type TemplateResult } from 'lit';
import type { CardHeadingLevel, CardInset, CardSurface } from '@design-schema/lit';

interface CardArgs {
  heading?: string | undefined;
  headingLevel: CardHeadingLevel;
  inset: CardInset;
  surface: CardSurface;
  interactive: boolean;
  focusable: boolean;
  children: string;
}

const body = (args: CardArgs): TemplateResult =>
  args.interactive
    ? html`<ds-link href="#card" label=${args.children}></ds-link>`
    : html`<ds-text>${args.children}</ds-text>`;

html`
  <div style="inline-size: min(100%, 24rem)">
    <ds-card heading="Notification settings">
      ${body({ heading: 'Notification settings', children: 'Choose which updates you want to hear about, and how.' })}
    </ds-card>
  </div>
`;

